	body.type = "sine";
	body.frequency.setValueAtTime(freq, startAt);
	const bodyGain = ctx.createGain();
	bodyGain.gain.setValueAtTime(1e-4, startAt);
	bodyGain.gain.linearRampToValueAtTime(vol, startAt + .008);
	bodyGain.gain.exponentialRampToValueAtTime(1e-4, startAt + dur);
