	over.type = "sine";
	over.frequency.setValueAtTime(freq * 3.98, startAt);
	const overGain = ctx.createGain();
	overGain.gain.setValueAtTime(1e-4, startAt);
	overGain.gain.linearRampToValueAtTime(vol * .26, startAt + .004);
	overGain.gain.exponentialRampToValueAtTime(1e-4, startAt + .065);
