		const env = ctx.createGain();
		osc.type = "sine";
		osc.frequency.setValueAtTime(freq * ratio, startAt);
		env.gain.setValueAtTime(1e-4, startAt);
		env.gain.linearRampToValueAtTime(vol * amp, startAt + .007);
		env.gain.exponentialRampToValueAtTime(1e-4, startAt + pDur);
		osc.connect(env);
		env.connect(mix);
		osc.start(startAt);
		osc.stop(startAt + pDur + .03);
