/** 4. Pizzicato String Bass — Warm plucked cello/bass foundation */
function playPizzBassNote(g, dest, freq, startAt, vol = .22, dur = .75) {
	if (!acquireVoice(dur)) return;
	const { ctx } = g;
	const osc = ctx.createOscillator();
	osc.type = "triangle";
	osc.frequency.setValueAtTime(freq, startAt);
	const sub = ctx.createOscillator();
	sub.type = "sine";
	sub.frequency.setValueAtTime(freq, startAt);
	const filter = ctx.createBiquadFilter();
	filter.type = "lowpass";
	filter.frequency.setValueAtTime(freq * 4.5, startAt);
	filter.frequency.exponentialRampToValueAtTime(Math.max(180, freq * 1.3), startAt + .22);
	const env = ctx.createGain();
	env.gain.setValueAtTime(1e-4, startAt);
	env.gain.linearRampToValueAtTime(vol, startAt + .015);
	env.gain.exponentialRampToValueAtTime(1e-4, startAt + dur);
	osc.connect(filter);
	sub.connect(filter);
	filter.connect(env);
	env.connect(dest);
	osc.start(startAt);
	sub.start(startAt);
	osc.stop(startAt + dur + .04);
	sub.stop(startAt + dur + .04);
}
/** 5. Conservatory Warm Pad — Silky detuned string swell */
function playWarmPadChord(g, dest, freqs, startAt, vol = .055, dur = 2.6) {
	if (!acquireVoice(dur)) return;
	const { ctx } = g;
	const filter = ctx.createBiquadFilter();
	filter.type = "lowpass";
	filter.frequency.setValueAtTime(1050, startAt);
	const env = ctx.createGain();
	env.gain.setValueAtTime(1e-4, startAt);
	env.gain.linearRampToValueAtTime(vol, startAt + dur * .28);
	env.gain.setValueAtTime(vol * .88, startAt + dur * .65);
	env.gain.exponentialRampToValueAtTime(1e-4, startAt + dur);
	freqs.forEach((f, idx) => {
		const osc = ctx.createOscillator();
		osc.type = idx === 0 ? "sine" : "triangle";
		osc.frequency.setValueAtTime(f * (1 + (idx % 2 === 0 ? .0022 : -.0022)), startAt);
		osc.connect(filter);
		osc.start(startAt);
		osc.stop(startAt + dur + .05);
	});
	filter.connect(env);
	connectWithPanAndReverb(g, env, dest, 0, .35);
}
/** 6. Playful Bassoon / Cartoon Woodwind — Expressive reedy tone for comedic moments */
function playBassoonNote(g, dest, startFreq, endFreq, startAt, vol = .14, dur = .36) {
	if (!acquireVoice(dur)) return;
	const { ctx } = g;
	const saw = ctx.createOscillator();
	saw.type = "sawtooth";
	saw.frequency.setValueAtTime(startFreq, startAt);
	if (Math.abs(endFreq - startFreq) > .5) saw.frequency.exponentialRampToValueAtTime(endFreq, startAt + dur * .85);
	const tri = ctx.createOscillator();
	tri.type = "triangle";
	tri.frequency.setValueAtTime(startFreq * .5, startAt);
	if (Math.abs(endFreq - startFreq) > .5) tri.frequency.exponentialRampToValueAtTime(endFreq * .5, startAt + dur * .85);
	const formant = ctx.createBiquadFilter();
	formant.type = "bandpass";
	formant.frequency.setValueAtTime(Math.max(380, startFreq * 2.1), startAt);
	formant.Q.setValueAtTime(2.6, startAt);
	const bodyLp = ctx.createBiquadFilter();
	bodyLp.type = "lowpass";
	bodyLp.frequency.setValueAtTime(1450, startAt);
	const env = ctx.createGain();
	env.gain.setValueAtTime(1e-4, startAt);
	env.gain.linearRampToValueAtTime(vol, startAt + .032);
	env.gain.setValueAtTime(vol * .82, startAt + dur * .55);
	env.gain.exponentialRampToValueAtTime(1e-4, startAt + dur);
	saw.connect(formant);
	tri.connect(bodyLp);
	formant.connect(bodyLp);
	bodyLp.connect(env);
	connectWithPanAndReverb(g, env, dest, 0, .28);
	saw.start(startAt);
	tri.start(startAt);
	saw.stop(startAt + dur + .04);
	tri.stop(startAt + dur + .04);
}
/** Delicate wooden shaker / soft clave tick for Challenge BGM stem */
function playSoftShaker(g, dest, startAt, accent = false) {
	if (!acquireVoice(.08)) return;
	const { ctx } = g;
	const src = ctx.createBufferSource();
	src.buffer = g.noiseBuffer;
	const bp = ctx.createBiquadFilter();
	bp.type = "bandpass";
	bp.frequency.setValueAtTime(accent ? 4200 : 3200, startAt);
	bp.Q.setValueAtTime(3.2, startAt);
	const env = ctx.createGain();
	env.gain.setValueAtTime(1e-4, startAt);
	env.gain.linearRampToValueAtTime(accent ? .045 : .025, startAt + .006);
	env.gain.exponentialRampToValueAtTime(1e-4, startAt + .055);
	src.connect(bp);
	bp.connect(env);
	env.connect(dest);
	src.start(startAt, randRange(0, .4), .07);
}
